FILE: app/src/hover.ts
```ts
import { createAnimationTask, addAnimationTask } from "@babylonjs/lite";
import type { AnimationManager } from "@babylonjs/lite";

export function startHover(manager: AnimationManager, node: { position: { y: number } }): (strength: number) => void {
    const restHeight = node.position.y;
    let strength = 1;
    let elapsed = 0;

    const task = createAnimationTask((_mgr, deltaMs) => {
        elapsed += deltaMs / 1000;
        const t = elapsed % 1;
        const offset = t < 0.5 ? t : 1 - t;
        node.position.y = restHeight + strength * offset;
    });

    addAnimationTask(manager, task);

    return (s: number) => {
        strength = s;
    };
}
```

I wrote `src/hover.ts` as a custom animation task that accumulates elapsed time, computes a triangular-wave offset (linear rise to 0.5 over 0.5 s, linear fall back over 0.5 s), multiplies it by the current strength, and writes the result onto `node.position.y` each update. I had no uncertainty—the task-based approach sidesteps the blending/weight complexities in the notes and keeps each pickup's state (rest height, strength, phase) in its own closure so many can share one manager safely.
